## Authentication Token Storage

### Best Practice: Store Token Securely on Flutter Side

Add to your pubspec.yaml:
```yaml
dependencies:
  flutter_secure_storage: ^9.2.4
```

In your Cubit/BLoC/Service:
```dart
import 'package:flutter_secure_storage/flutter_secure_storage.dart';

class AuthTokenService {
  static const storage = FlutterSecureStorage();

  static Future<void> saveToken(String token) async {
    await storage.write(key: 'auth_token', value: token);
  }

  static Future<String?> getToken() async {
    return await storage.read(key: 'auth_token');
  }

  static Future<void> deleteToken() async {
    await storage.delete(key: 'auth_token');
  }
}
```

---

## Making API Calls with Auth Token

### Example: Authenticated API Service

```dart
class ApiService {
  final String baseUrl;
  final Dio dio = Dio();

  ApiService({required this.baseUrl});

  Future<T> getWithAuth<T>(
    String endpoint, {
    required T Function(Map<String, dynamic>) fromJson,
    required String token,
  }) async {
    try {
      final response = await dio.get(
        '$baseUrl$endpoint',
        options: Options(
          headers: {
            'Authorization': 'Bearer $token',
            'Content-Type': 'application/json',
          },
        ),
      );
      return fromJson(response.data);
    } catch (e) {
      throw Exception('API Error: $e');
    }
  }
}
```

---

## Complete Example: DashboardCubit with API Integration

```dart
class DashboardCubit extends Cubit<DashboardState> {
  final ApiService apiService;
  final AuthTokenService authTokenService;

  DashboardCubit({
    required this.apiService,
    required this.authTokenService,
  }) : super(const DashboardState.initial());

  Future<void> initializeDashboard({
    required String email,
    required String userId,
    required String token,
  }) async {
    emit(const DashboardState.loading());
    try {
      // Save token for later use
      await authTokenService.saveToken(token);

      // Fetch dashboard data with authenticated request
      final dashboardData = await apiService.getWithAuth<DashboardData>(
        '/dashboard/$userId',
        fromJson: (json) => DashboardData.fromJson(json),
        token: token,
      );

      emit(DashboardState.loaded(
        dashboardData: dashboardData,
        userEmail: email,
        userId: userId,
      ));
    } catch (e) {
      emit(DashboardState.error(message: e.toString()));
    }
  }

  Future<void> refreshDashboard() async {
    final token = await authTokenService.getToken();
    if (token == null) {
      emit(const DashboardState.error(message: 'No auth token found'));
      return;
    }

    // Similar fetch logic as above
    emit(const DashboardState.loading());
    try {
      // Fetch updated data
    } catch (e) {
      emit(DashboardState.error(message: e.toString()));
    }
  }

  Future<void> logout() async {
    await authTokenService.deleteToken();
    emit(const DashboardState.initial());
  }
}
```

