```

### Replace success state handling:
```kotlin
is LoginViewModel.LoginState.Success -> {
    showLoading(false)
    Toast.makeText(requireContext(), state.message, Toast.LENGTH_SHORT).show()

    // Navigate to Flutter Dashboard with user session data
    navigateToFlutterDashboard()
}
```

### Add this new method:
```kotlin
private fun navigateToFlutterDashboard() {
    // Retrieve user session from TokenManager
    val tokenManager = (requireActivity().application as AuthApplication).tokenManager

    CoroutineScope(Dispatchers.Main).launch {
        try {
            // Collect the flows to get the data
            var email: String? = null
            var userId: String? = null
            var token: String? = null

            // Use a coroutine scope to collect flows
            withContext(Dispatchers.IO) {
                tokenManager.getUserEmail().collect { email = it }
                tokenManager.getUserId().collect { userId = it }
                tokenManager.getAccessToken().collect { token = it }
            }

            if (!email.isNullOrEmpty() && !userId.isNullOrEmpty() && !token.isNullOrEmpty()) {
                // Launch FlutterDashboardActivity with user data
                val intent = Intent(requireContext(), FlutterDashboardActivity::class.java).apply {
                    putExtra("email", email)
                    putExtra("userId", userId)
                    putExtra("token", token)
                    flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
                }
                startActivity(intent)
                requireActivity().finish()
            } else {
                Toast.makeText(requireContext(), "Error: User session incomplete", Toast.LENGTH_SHORT).show()
            }
        } catch (e: Exception) {
            Toast.makeText(requireContext(), "Error navigating to dashboard: ${e.message}", Toast.LENGTH_SHORT).show()
        }
    }
}
```

