## 5. dashboard_page.dart - Complete File (Updated)

```dart
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

class DashboardPage extends StatefulWidget {
	const DashboardPage({super.key});

	@override
	State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
	// Method channel for communicating with Android
	static const platform = MethodChannel('com.example.flutter/dashboard');

	String? userEmail;
	String? userId;
	String? token;
	bool isLoading = true;
	String? errorMessage;

	@override
	void initState() {
		super.initState();
		_getUserSessionFromAndroid();
	}

	/// Retrieve user session data from Android
	Future<void> _getUserSessionFromAndroid() async {
		try {
			final result = await platform.invokeMethod<Map>('getUserSession');

			if (result != null) {
				setState(() {
					userEmail = result['email'] as String?;
					userId = result['userId'] as String?;
					token = result['token'] as String?;
					isLoading = false;
				});

				// TODO: Pass data to your BLoC/Cubit here
				// Example:
				// context.read<DashboardCubit>().initializeDashboard(
				//   email: userEmail,
				//   userId: userId,
				//   token: token,
				// );

				debugPrint('Dashboard initialized with user: $userEmail');
			} else {
				setState(() {
					errorMessage = "No user session found";
					isLoading = false;
				});
			}
		} on PlatformException catch (e) {
			setState(() {
				errorMessage = "Failed to get user session: ${e.message}";
				isLoading = false;
			});
			debugPrint('PlatformException: ${e.code} - ${e.message}');
		} catch (e) {
			setState(() {
				errorMessage = "Error: $e";
				isLoading = false;
			});
			debugPrint('Exception: $e');
		}
	}

	@override
	Widget build(BuildContext context) {
		if (isLoading) {
			return const Scaffold(
				body: Center(
					child: CircularProgressIndicator(),
				),
			);
		}

		if (errorMessage != null) {
			return Scaffold(
				body: Center(
					child: Column(
						mainAxisAlignment: MainAxisAlignment.center,
						children: [
							Text(
								'Error',
								style: Theme.of(context).textTheme.headlineSmall,
							),
							const SizedBox(height: 16),
							Text(errorMessage!),
							const SizedBox(height: 24),
							ElevatedButton(
								onPressed: _getUserSessionFromAndroid,
								child: const Text('Retry'),
							),
						],
					),
				),
			);
		}

		return Scaffold(
			appBar: AppBar(
				title: const Text('Dashboard'),
			),
			body: SingleChildScrollView(
				padding: const EdgeInsets.all(16),
				child: Column(
					crossAxisAlignment: CrossAxisAlignment.start,
					children: [
						Text(
							'User Information',
							style: Theme.of(context).textTheme.headlineSmall,
						),
						const SizedBox(height: 16),
						_buildInfoCard('Email', userEmail ?? 'N/A'),
						const SizedBox(height: 12),
						_buildInfoCard('User ID', userId ?? 'N/A'),
						const SizedBox(height: 12),
						_buildInfoCard('Token', token?.substring(0, 20) ?? 'N/A' + (token != null && token!.length > 20 ? '...' : '')),
						const SizedBox(height: 32),
						Center(
							child: Text(
								'Dashboard Content',
								style: Theme.of(context).textTheme.titleMedium,
							),
						),
					],
				),
			),
		);
	}

	Widget _buildInfoCard(String label, String value) {
		return Card(
			child: Padding(
				padding: const EdgeInsets.all(12),
				child: Column(
					crossAxisAlignment: CrossAxisAlignment.start,
					children: [
						Text(
							label,
							style: const TextStyle(
								fontWeight: FontWeight.bold,
								fontSize: 12,
								color: Colors.grey,
							),
						),
						const SizedBox(height: 4),
						Text(
							value,
							style: const TextStyle(fontSize: 14),
						),
					],
				),
			),
		);
	}

	@override
	void dispose() {
		super.dispose();
	}
}
```

