import 'package:flutter/material.dart';
import '../../../../services/api_service.dart';

class ProfilePage extends StatefulWidget {
  final String? userEmail;
  final String? userId;
  final String? token;
  final String? displayName;
  final String? fullName;
  final String? phoneNumber;
  final String? preferredLanguage;
  final bool? mfaEnabled;
  final bool? emailVerified;
  final String? role;
  final String? createdAt;

  const ProfilePage({
    super.key,
    this.userEmail,
    this.userId,
    this.token,
    this.displayName,
    this.fullName,
    this.phoneNumber,
    this.preferredLanguage,
    this.mfaEnabled,
    this.emailVerified,
    this.role,
    this.createdAt,
  });

  @override
  State<ProfilePage> createState() => _ProfilePageState();
}

class _ProfilePageState extends State<ProfilePage> {
  bool _isLoading = true;
  Map<String, dynamic>? _profileData;
  String? _errorMessage;

  @override
  void initState() {
    super.initState();
    _loadProfile();
  }

  Future<void> _loadProfile() async {
    setState(() {
      _isLoading = true;
      _errorMessage = null;
    });

    // Use data passed from dashboard (which already has backend data)
    if (mounted) {
      setState(() {
        _profileData = {
          'email': widget.userEmail ?? 'N/A',
          'userId': widget.userId ?? 'N/A',
          'displayName': widget.displayName,
          'fullName': widget.fullName,
          'phoneNumber': widget.phoneNumber,
          'preferredLanguage': widget.preferredLanguage,
          'mfaEnabled': widget.mfaEnabled,
          'emailVerified': widget.emailVerified,
          'role': widget.role,
          'createdAt': widget.createdAt,
        };
        _isLoading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF8FAFC),
      appBar: AppBar(
        title: const Text(
          'My Profile',
          style: TextStyle(
            fontWeight: FontWeight.bold,
            color: Color(0xFF0F172A),
          ),
        ),
        backgroundColor: Colors.white,
        elevation: 0,
        iconTheme: const IconThemeData(color: Color(0xFF0F172A)),
        actions: [
          IconButton(
            icon: const Icon(Icons.refresh_rounded),
            onPressed: _loadProfile,
            tooltip: 'Refresh',
          ),
        ],
      ),
      body: _buildBody(),
    );
  }

  Widget _buildBody() {
    if (_isLoading) {
      return const Center(
        child: CircularProgressIndicator(),
      );
    }

    if (_errorMessage != null) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              const Icon(
                Icons.error_outline_rounded,
                size: 64,
                color: Color(0xFFEF4444),
              ),
              const SizedBox(height: 16),
              const Text(
                'Failed to load profile',
                style: TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                  color: Color(0xFF0F172A),
                ),
              ),
              const SizedBox(height: 8),
              Text(
                _errorMessage!,
                textAlign: TextAlign.center,
                style: const TextStyle(
                  fontSize: 14,
                  color: Color(0xFF64748B),
                ),
              ),
              const SizedBox(height: 24),
              ElevatedButton.icon(
                onPressed: _loadProfile,
                icon: const Icon(Icons.refresh_rounded),
                label: const Text('Retry'),
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF6366F1),
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 24,
                    vertical: 12,
                  ),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                ),
              ),
            ],
          ),
        ),
      );
    }

    return RefreshIndicator(
      onRefresh: _loadProfile,
      child: SingleChildScrollView(
        physics: const AlwaysScrollableScrollPhysics(),
        child: Padding(
          padding: const EdgeInsets.all(20.0),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // Profile Header Card
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(24),
                decoration: BoxDecoration(
                  gradient: const LinearGradient(
                    colors: [Color(0xFF6366F1), Color(0xFF4F46E5)],
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                  ),
                  borderRadius: BorderRadius.circular(20),
                  boxShadow: [
                    BoxShadow(
                      color: const Color(0xFF6366F1).withOpacity(0.3),
                      blurRadius: 12,
                      offset: const Offset(0, 4),
                    ),
                  ],
                ),
                child: Column(
                  children: [
                    Container(
                      width: 80,
                      height: 80,
                      decoration: BoxDecoration(
                        color: Colors.white.withOpacity(0.2),
                        shape: BoxShape.circle,
                      ),
                      child: const Icon(
                        Icons.person_rounded,
                        size: 48,
                        color: Colors.white,
                      ),
                    ),
                    const SizedBox(height: 16),
                    Text(
                      _getDisplayName(),
                      style: const TextStyle(
                        fontSize: 24,
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      widget.userEmail ?? 'No email',
                      style: TextStyle(
                        fontSize: 14,
                        color: Colors.white.withOpacity(0.9),
                      ),
                    ),
                  ],
                ),
              ),

              const SizedBox(height: 24),

              // Profile Details
              const Text(
                'Profile Details',
                style: TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                  color: Color(0xFF0F172A),
                ),
              ),
              const SizedBox(height: 12),

              _buildProfileCard(),

              const SizedBox(height: 24),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildProfileCard() {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(16),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.05),
            blurRadius: 10,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _buildInfoRow('User ID', widget.userId ?? 'N/A'),
          const Divider(height: 24),
          _buildInfoRow('Email', widget.userEmail ?? 'N/A'),

          // Display additional profile data from API if available
          if (_profileData != null) ...[
            if (_profileData!['displayName'] != null && _profileData!['displayName'].toString().isNotEmpty) ...[
              const Divider(height: 24),
              _buildInfoRow('Display Name', _profileData!['displayName'].toString()),
            ],
            if (_profileData!['fullName'] != null && _profileData!['fullName'].toString().isNotEmpty) ...[
              const Divider(height: 24),
              _buildInfoRow('Full Name', _profileData!['fullName'].toString()),
            ],
            if (_profileData!['phoneNumber'] != null && _profileData!['phoneNumber'].toString().isNotEmpty) ...[
              const Divider(height: 24),
              _buildInfoRow('Phone Number', _profileData!['phoneNumber'].toString()),
            ],
            if (_profileData!['role'] != null) ...[
              const Divider(height: 24),
              _buildInfoRow('Role', _profileData!['role'].toString()),
            ],
            if (_profileData!['mfaEnabled'] != null) ...[
              const Divider(height: 24),
              _buildInfoRow('MFA Enabled', _profileData!['mfaEnabled'] == true ? 'Yes' : 'No'),
            ],
            if (_profileData!['emailVerified'] != null) ...[
              const Divider(height: 24),
              _buildInfoRow('Email Verified', _profileData!['emailVerified'] == true ? 'Yes' : 'No'),
            ],
            if (_profileData!['preferredLanguage'] != null && _profileData!['preferredLanguage'].toString().isNotEmpty) ...[
              const Divider(height: 24),
              _buildInfoRow('Language', _profileData!['preferredLanguage'].toString().toUpperCase()),
            ],
            if (_profileData!['createdAt'] != null && _profileData!['createdAt'].toString().isNotEmpty) ...[
              const Divider(height: 24),
              _buildInfoRow('Member Since', _formatDate(_profileData!['createdAt'].toString())),
            ],
          ],
        ],
      ),
    );
  }

  Widget _buildInfoRow(String label, String value) {
    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        SizedBox(
          width: 100,
          child: Text(
            label,
            style: const TextStyle(
              fontSize: 14,
              fontWeight: FontWeight.w600,
              color: Color(0xFF64748B),
            ),
          ),
        ),
        const SizedBox(width: 16),
        Expanded(
          child: Text(
            value,
            style: const TextStyle(
              fontSize: 14,
              color: Color(0xFF0F172A),
            ),
          ),
        ),
      ],
    );
  }

  String _getDisplayName() {
    if (widget.userEmail == null) return 'Guest';
    final name = widget.userEmail!.split('@')[0];
    return name
        .split('.')
        .map((s) => s.isNotEmpty ? s[0].toUpperCase() + s.substring(1) : s)
        .join(' ');
  }

  String _formatKey(String key) {
    // Convert camelCase or snake_case to Title Case
    return key
        .replaceAllMapped(RegExp(r'[A-Z]'), (match) => ' ${match.group(0)}')
        .replaceAll('_', ' ')
        .split(' ')
        .map((word) => word.isNotEmpty
          ? word[0].toUpperCase() + word.substring(1).toLowerCase()
          : '')
        .join(' ')
        .trim();
  }

  String _formatDate(String dateString) {
    try {
      final date = DateTime.parse(dateString);
      return '${date.year}-${date.month.toString().padLeft(2, '0')}-${date.day.toString().padLeft(2, '0')}';
    } catch (e) {
      return dateString;
    }
  }
}

import 'package:flutter/material.dart';
import '../../../../services/api_service.dart';

class ProfilePage extends StatefulWidget {
  final String? userEmail;
  final String? userId;
  final String? token;
  final String? displayName;
  final String? fullName;
  final String? phoneNumber;
  final String? preferredLanguage;
  final bool? mfaEnabled;
  final bool? emailVerified;
  final String? role;
  final String? createdAt;

  const ProfilePage({
    super.key,
    this.userEmail,
    this.userId,
    this.token,
    this.displayName,
    this.fullName,
    this.phoneNumber,
    this.preferredLanguage,
    this.mfaEnabled,
    this.emailVerified,
    this.role,
    this.createdAt,
  });

  @override
  State<ProfilePage> createState() => _ProfilePageState();
}

class _ProfilePageState extends State<ProfilePage> {
  bool _isLoading = true;
  Map<String, dynamic>? _profileData;
  String? _errorMessage;

  @override
  void initState() {
    super.initState();
    _loadProfile();
  }

  Future<void> _loadProfile() async {
    setState(() {
      _isLoading = true;
      _errorMessage = null;
    });

    // Use data passed from dashboard (which already has backend data)
    if (mounted) {
      setState(() {
        _profileData = {
          'email': widget.userEmail ?? 'N/A',
          'userId': widget.userId ?? 'N/A',
          'displayName': widget.displayName,
          'fullName': widget.fullName,
          'phoneNumber': widget.phoneNumber,
          'preferredLanguage': widget.preferredLanguage,
          'mfaEnabled': widget.mfaEnabled,
          'emailVerified': widget.emailVerified,
          'role': widget.role,
          'createdAt': widget.createdAt,
        };
        _isLoading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF8FAFC),
      appBar: AppBar(
        title: const Text(
          'My Profile',
          style: TextStyle(
            fontWeight: FontWeight.bold,
            color: Color(0xFF0F172A),
          ),
        ),
        backgroundColor: Colors.white,
        elevation: 0,
        iconTheme: const IconThemeData(color: Color(0xFF0F172A)),
        actions: [
          IconButton(
            icon: const Icon(Icons.refresh_rounded),
            onPressed: _loadProfile,
            tooltip: 'Refresh',
          ),
        ],
      ),
      body: _buildBody(),
    );
  }

  Widget _buildBody() {
    if (_isLoading) {
      return const Center(
        child: CircularProgressIndicator(),
      );
    }

    if (_errorMessage != null) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              const Icon(
                Icons.error_outline_rounded,
                size: 64,
                color: Color(0xFFEF4444),
              ),
              const SizedBox(height: 16),
              const Text(
                'Failed to load profile',
                style: TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                  color: Color(0xFF0F172A),
                ),
              ),
              const SizedBox(height: 8),
              Text(
                _errorMessage!,
                textAlign: TextAlign.center,
                style: const TextStyle(
                  fontSize: 14,
                  color: Color(0xFF64748B),
                ),
              ),
              const SizedBox(height: 24),
              ElevatedButton.icon(
                onPressed: _loadProfile,
                icon: const Icon(Icons.refresh_rounded),
                label: const Text('Retry'),
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF6366F1),
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 24,
                    vertical: 12,
                  ),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                ),
              ),
            ],
          ),
        ),
      );
    }

    return RefreshIndicator(
      onRefresh: _loadProfile,
      child: SingleChildScrollView(
        physics: const AlwaysScrollableScrollPhysics(),
        child: Padding(
          padding: const EdgeInsets.all(20.0),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // Profile Header Card
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(24),
                decoration: BoxDecoration(
                  gradient: const LinearGradient(
                    colors: [Color(0xFF6366F1), Color(0xFF4F46E5)],
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                  ),
                  borderRadius: BorderRadius.circular(20),
                  boxShadow: [
                    BoxShadow(
                      color: const Color(0xFF6366F1).withOpacity(0.3),
                      blurRadius: 12,
                      offset: const Offset(0, 4),
                    ),
                  ],
                ),
                child: Column(
                  children: [
                    Container(
                      width: 80,
                      height: 80,
                      decoration: BoxDecoration(
                        color: Colors.white.withOpacity(0.2),
                        shape: BoxShape.circle,
                      ),
                      child: const Icon(
                        Icons.person_rounded,
                        size: 48,
                        color: Colors.white,
                      ),
                    ),
                    const SizedBox(height: 16),
                    Text(
                      _getDisplayName(),
                      style: const TextStyle(
                        fontSize: 24,
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      widget.userEmail ?? 'No email',
                      style: TextStyle(
                        fontSize: 14,
                        color: Colors.white.withOpacity(0.9),
                      ),
                    ),
                  ],
                ),
              ),

              const SizedBox(height: 24),

              // Profile Details
              const Text(
                'Profile Details',
                style: TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                  color: Color(0xFF0F172A),
                ),
              ),
              const SizedBox(height: 12),

              _buildProfileCard(),

              const SizedBox(height: 24),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildProfileCard() {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(24),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(20),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.08),
            blurRadius: 20,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // User ID Section
          _buildInfoSection(
            icon: Icons.fingerprint_rounded,
            label: 'User ID',
            value: widget.userId ?? 'N/A',
          ),

          const SizedBox(height: 20),

          // Email Section
          _buildInfoSection(
            icon: Icons.email_rounded,
            label: 'Email',
            value: widget.userEmail ?? 'N/A',
          ),

          // Display Name (if available)
          if (_profileData?['displayName'] != null && _profileData!['displayName'].toString().isNotEmpty) ...[
            const SizedBox(height: 20),
            _buildInfoSection(
              icon: Icons.person_rounded,
              label: 'Display Name',
              value: _profileData!['displayName'].toString(),
            ),
          ],

          // Full Name (if available and different from display name)
          if (_profileData?['fullName'] != null && 
              _profileData!['fullName'].toString().isNotEmpty &&
              _profileData!['fullName'] != _profileData?['displayName']) ...[
            const SizedBox(height: 20),
            _buildInfoSection(
              icon: Icons.badge_rounded,
              label: 'Full Name',
              value: _profileData!['fullName'].toString(),
            ),
          ],

          // Phone Number (if available)
          if (_profileData?['phoneNumber'] != null && _profileData!['phoneNumber'].toString().isNotEmpty) ...[
            const SizedBox(height: 20),
            _buildInfoSection(
              icon: Icons.phone_rounded,
              label: 'Phone Number',
              value: _profileData!['phoneNumber'].toString(),
            ),
          ],

          // Role
          if (_profileData?['role'] != null) ...[
            const SizedBox(height: 20),
            _buildInfoSection(
              icon: Icons.work_rounded,
              label: 'Role',
              value: _profileData!['role'].toString(),
            ),
          ],

          const SizedBox(height: 24),
          const Divider(height: 1),
          const SizedBox(height: 24),

          // Security & Verification Section
          const Text(
            'Security & Verification',
            style: TextStyle(
              fontSize: 16,
              fontWeight: FontWeight.bold,
              color: Color(0xFF0F172A),
            ),
          ),
          const SizedBox(height: 16),

          // MFA Status
          if (_profileData?['mfaEnabled'] != null) ...[
            _buildStatusRow(
              icon: Icons.security_rounded,
              label: 'Two-Factor Authentication',
              isEnabled: _profileData!['mfaEnabled'] == true,
            ),
          ],

          // Email Verification
          if (_profileData?['emailVerified'] != null) ...[
            const SizedBox(height: 12),
            _buildStatusRow(
              icon: Icons.verified_rounded,
              label: 'Email Verified',
              isEnabled: _profileData!['emailVerified'] == true,
            ),
          ],

          // Language
          if (_profileData?['preferredLanguage'] != null && _profileData!['preferredLanguage'].toString().isNotEmpty) ...[
            const SizedBox(height: 24),
            const Divider(height: 1),
            const SizedBox(height: 24),
            _buildInfoSection(
              icon: Icons.language_rounded,
              label: 'Preferred Language',
              value: _profileData!['preferredLanguage'].toString().toUpperCase(),
            ),
          ],
        ],
      ),
    );
  }

  Widget _buildInfoSection({
    required IconData icon,
    required String label,
    required String value,
  }) {
    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Container(
          padding: const EdgeInsets.all(10),
          decoration: BoxDecoration(
            color: const Color(0xFF6366F1).withOpacity(0.1),
            borderRadius: BorderRadius.circular(12),
